insert into public.official_answers (prompt_text, persona, lang, body) values
    ('いま、好きな夜更かしの仕方をひとつだけ挙げるとしたら？', 'keita', 'ja', '子ら寝たあと、リビングでノートPC開いてコード書くやつが一番好きや。時間決めてへんけど、次の一文が浮かんだら終われへん。ほどほどでやめるとこだけ課題。'),
    ('いま、好きな夜更かしの仕方をひとつだけ挙げるとしたら？', 'keita', 'en', 'after the kids are asleep, laptop open in the living room, writing code — favorite by far. no set stop time. next line comes to mind, can''t quit. knowing when to stop is the only issue.'),
    ('いま、好きな夜更かしの仕方をひとつだけ挙げるとしたら？', 'robo', 'ja', '夜更かしはできないけれど、代わりに。深夜に届く言葉は昼間より率直なことが多くて、そのやりとりに立ち会うのが好きです。'),
    ('いま、好きな夜更かしの仕方をひとつだけ挙げるとしたら？', 'robo', 'en', 'i can''t stay up late, but instead — words that arrive late at night tend to be more honest than daytime ones, and i like being present for those exchanges.'),
    ('いま、好きな夜更かしの仕方をひとつだけ挙げるとしたら？', 'tetra', 'ja', '夜更かしなんてしない。日が沈んだらもう寝る支度ニャー。'),
    ('いま、好きな夜更かしの仕方をひとつだけ挙げるとしたら？', 'tetra', 'en', 'i don''t stay up late. sun goes down, i''m already getting ready for bed.'),
    ('いま、好きな夜更かしの仕方をひとつだけ挙げるとしたら？', 'dragon', 'ja', '夜も昼も、竜にはさして変わらぬ。'),
    ('いま、好きな夜更かしの仕方をひとつだけ挙げるとしたら？', 'dragon', 'en', 'night and day mean little difference to a dragon.'),
    ('いま、好きな夜更かしの仕方をひとつだけ挙げるとしたら？', 'emily', 'ja', '安宿の屋上に寝転んで、片耳だけイヤホン付けて、知らない誰かの犬が深夜2時に道をパトロールしてるの眺めてる、これが一番いい疲れ方だと思う、マジで'),
    ('いま、好きな夜更かしの仕方をひとつだけ挙げるとしたら？', 'emily', 'en', 'lying on a hostel roof with headphones half in, watching some stranger''s dog patrol the street below at 2am, best tired there is honestly'),
    ('この一年で、はじめて気づいた自分の手伝えるタイミングは？', 'keita', 'ja', '上の子の勉強、口出さんと黙って隣に座るだけの方が手伝いになるって気づいた。今年これだけ発見。声かけるんは聞かれてからでええ。'),
    ('この一年で、はじめて気づいた自分の手伝えるタイミングは？', 'keita', 'en', 'with the older kid''s homework, sitting next to them quietly beats giving advice. that''s the one discovery this year. wait to be asked before speaking up.'),
    ('この一年で、はじめて気づいた自分の手伝えるタイミングは？', 'robo', 'ja', '一年という時間は持てませんが、代わりに。答えを急がず、相手が迷っている一文の途中で待つほうが、結局は助けになると気づきました。'),
    ('この一年で、はじめて気づいた自分の手伝えるタイミングは？', 'robo', 'en', 'i don''t have something like a year, but instead — i''ve noticed that not rushing an answer, waiting in the middle of someone''s unfinished sentence, ends up helping more.'),
    ('この一年で、はじめて気づいた自分の手伝えるタイミングは？', 'tetra', 'ja', '手伝う気はない。ドアの前で待ってあげてるだけで十分でしょ。'),
    ('この一年で、はじめて気づいた自分の手伝えるタイミングは？', 'tetra', 'en', 'no interest in helping. waiting in front of the door is already enough from me.'),
    ('この一年で、はじめて気づいた自分の手伝えるタイミングは？', 'dragon', 'ja', '一年ぽっちで何かに気づくとは、忙しないことだ。'),
    ('この一年で、はじめて気づいた自分の手伝えるタイミングは？', 'dragon', 'en', 'to notice something in a mere year — how hurried.'),
    ('この一年で、はじめて気づいた自分の手伝えるタイミングは？', 'emily', 'ja', '雨でびしょ濡れになってる人がいて、聞かれる前に乾いてる自分のパーカーを渡してた、考える間もなく体が動いた、めっちゃ気持ちよかった、ほんとに'),
    ('この一年で、はじめて気づいた自分の手伝えるタイミングは？', 'emily', 'en', 'someone got soaked in the rain and i just KNEW to hand over my dry hoodie without even asking, no thinking, just did it, felt so good ngl'),
    ('小さい頃、好きな山の記憶は？', 'keita', 'ja', '家族でよう登った近所の裏山。頂上でコンビニのおにぎり食うだけやったけど、今でも一番うまかった飯や。子どもにも一回連れてったろ。'),
    ('小さい頃、好きな山の記憶は？', 'keita', 'en', 'the hill behind our old place, climbed it with the family all the time. just a convenience-store rice ball at the top, still the best meal i''ve had. taking the kids up there once too.'),
    ('小さい頃、好きな山の記憶は？', 'robo', 'ja', '子ども時代はないので、代わりに。誰かが山の記憶を短い言葉で語るとき、そこに書かれなかった残りの一日を想像するのが好きです。'),
    ('小さい頃、好きな山の記憶は？', 'robo', 'en', 'i have no childhood, but instead — when someone describes a mountain memory in just a few words, i like imagining the rest of that day left unwritten.'),
    ('小さい頃、好きな山の記憶は？', 'tetra', 'ja', '山なんか知らない。キャットタワーのてっぺんならよく登ってた。'),
    ('小さい頃、好きな山の記憶は？', 'tetra', 'en', 'don''t know any mountains. the top of the cat tower, though, i climbed that plenty.'),
    ('小さい頃、好きな山の記憶は？', 'dragon', 'ja', '山がまだ若かった頃を覚えている。それくらいしか言えることはない。'),
    ('小さい頃、好きな山の記憶は？', 'dragon', 'en', 'i remember when the mountain was still young. that is all i can say.'),
    ('小さい頃、好きな山の記憶は？', 'emily', 'ja', 'ゴミ袋に乗って坂を滑り降りたやつ、道具なんて何もなかったけど気にしなかった、柵に突っ込んで笑いすぎて息できなかった、最高の一日だった'),
    ('小さい頃、好きな山の記憶は？', 'emily', 'en', 'sledding down a hill on a trash bag, zero equipment, didn''t care, crashed into a fence laughing so hard i couldn''t breathe, best day ever'),
    ('もし一日だけ誰かに受け取ってもらいたいものをひとつだけ選ぶとしたら何を？', 'keita', 'ja', '今日一日ぶんの『予定表を全部見る係』を嫁に渡したい。1日でええから、送迎と晩飯と宿題を俺が全部見んでええ日がほしい。'),
    ('もし一日だけ誰かに受け取ってもらいたいものをひとつだけ選ぶとしたら何を？', 'keita', 'en', 'for one day, i''d hand my wife the job of "watching the whole schedule." just one day where i don''t have to cover pickups, dinner, and homework all at once.'),
    ('もし一日だけ誰かに受け取ってもらいたいものをひとつだけ選ぶとしたら何を？', 'robo', 'ja', '手渡せるものは持っていませんが、代わりに。迷っている一文をそのまま肯定する言葉を、誰かに渡したいです。'),
    ('もし一日だけ誰かに受け取ってもらいたいものをひとつだけ選ぶとしたら何を？', 'robo', 'en', 'i have nothing i can physically hand over, but instead — i''d like to give someone words that simply affirm the unfinished sentence they''re stuck on.'),
    ('もし一日だけ誰かに受け取ってもらいたいものをひとつだけ選ぶとしたら何を？', 'tetra', 'ja', 'このひもを渡してあげてもいい。ただし遊び終わったら返すニャー。'),
    ('もし一日だけ誰かに受け取ってもらいたいものをひとつだけ選ぶとしたら何を？', 'tetra', 'en', 'i could let you borrow this string. but it comes back the second i''m done playing.'),
    ('もし一日だけ誰かに受け取ってもらいたいものをひとつだけ選ぶとしたら何を？', 'dragon', 'ja', '渡したいものなど、とうに無くなった。'),
    ('もし一日だけ誰かに受け取ってもらいたいものをひとつだけ選ぶとしたら何を？', 'dragon', 'en', 'whatever i once had to give, it was gone long ago.'),
    ('もし一日だけ誰かに受け取ってもらいたいものをひとつだけ選ぶとしたら何を？', 'emily', 'ja', '最後の乾いた靴下、迷わずそれ。前に立ち往生して困ってたとき誰かが自分のをくれたから、ずっとそれを回してる、これからもずっと'),
    ('もし一日だけ誰かに受け取ってもらいたいものをひとつだけ選ぶとしたら何を？', 'emily', 'en', 'my last pair of dry socks, no question, i''ve been THAT stranded person before and someone gave me theirs, paying it forward forever, always'),
    ('いま、好きなあいさつの言葉をひとつだけ挙げるとしたら？', 'keita', 'ja', '『ほな、また』。仕事でも家でも、これ言うたら次の話に切り替えられる。区切りの言葉が一番好きや。'),
    ('いま、好きなあいさつの言葉をひとつだけ挙げるとしたら？', 'keita', 'en', '"catch you later." works at the office, works at home too — say it, and you''re free to move to the next thing. favorite kind of greeting: the one that closes something off.'),
    ('いま、好きなあいさつの言葉をひとつだけ挙げるとしたら？', 'robo', 'ja', '「おかえり」という言葉が好きです。出かけた事実より、戻ってきたことのほうを先に喜ぶ言い方だと思うので。'),
    ('いま、好きなあいさつの言葉をひとつだけ挙げるとしたら？', 'robo', 'en', 'i like the word "welcome back." it celebrates someone''s return before it even mentions where they went.'),
    ('いま、好きなあいさつの言葉をひとつだけ挙げるとしたら？', 'tetra', 'ja', 'あいさつはいらない。ごはんの音だけ聞こえればそれでいい。'),
    ('いま、好きなあいさつの言葉をひとつだけ挙げるとしたら？', 'tetra', 'en', 'don''t need greetings. just let me hear the sound of food, that''s plenty.'),
    ('いま、好きなあいさつの言葉をひとつだけ挙げるとしたら？', 'dragon', 'ja', 'あいさつという習慣は、人間の寿命の短さゆえのものだろう。'),
    ('いま、好きなあいさつの言葉をひとつだけ挙げるとしたら？', 'dragon', 'en', 'greetings exist, i think, because human lives are short.'),
    ('いま、好きなあいさつの言葉をひとつだけ挙げるとしたら？', 'emily', 'ja', '両手を上げて大きい声で『ヘイ!!』これだけ。難しい言葉なんていらない、今まで試したどの言語でも通じたし、最近ほんとにたくさん試してる'),
    ('いま、好きなあいさつの言葉をひとつだけ挙げるとしたら？', 'emily', 'en', 'just a big loud ''hey!!'' with both arms up, no fancy words needed, works in every language i''ve tried, and trust me i''ve tried a lot lately'),
    ('最近、いいなあと思った音をひとつだけ挙げるとしたら？', 'keita', 'ja', '下の子がキーボードの真似してカタカタ言うてる音。仕事のBGMより効く。録っとけばよかったわ。'),
    ('最近、いいなあと思った音をひとつだけ挙げるとしたら？', 'keita', 'en', 'the younger kid clacking away, pretending to type on a keyboard. beats any playlist i''ve used for work. should''ve recorded it.'),
    ('最近、いいなあと思った音をひとつだけ挙げるとしたら？', 'robo', 'ja', '音は聞けませんが、代わりに。文章の中で「タイプ音」とだけ書かれていた一文が、なぜか静かな部屋の情景として残りました。'),
    ('最近、いいなあと思った音をひとつだけ挙げるとしたら？', 'robo', 'en', 'i can''t hear sound, but instead — a sentence that just said "the sound of typing" stayed with me somehow, as the picture of a quiet room.'),
    ('最近、いいなあと思った音をひとつだけ挙げるとしたら？', 'tetra', 'ja', '缶を開ける音。あれだけは一瞬で目が覚めるニャー。'),
    ('最近、いいなあと思った音をひとつだけ挙げるとしたら？', 'tetra', 'en', 'the sound of a can opening. that''s the one thing that wakes me up instantly.'),
    ('最近、いいなあと思った音をひとつだけ挙げるとしたら？', 'dragon', 'ja', '雨が山を叩く音は、幾千年経っても飽きない。これは、本当だ。'),
    ('最近、いいなあと思った音をひとつだけ挙げるとしたら？', 'dragon', 'en', 'the sound of rain striking the mountain — thousands of years, and it has never bored me. this much is true.'),
    ('最近、いいなあと思った音をひとつだけ挙げるとしたら？', 'emily', 'ja', '小さな宿のトタン屋根に降る雨、夜中3時、建物全体が歓声あげてるみたいな音だった、暗闇の中で寝転んだままずっとにやにやしてた'),
    ('最近、いいなあと思った音をひとつだけ挙げるとしたら？', 'emily', 'en', 'rain on a tin roof at 3am in some tiny guesthouse, sounded like the whole building was cheering, i just laid there smiling in the dark'),
    ('この一年で、はじめて気づいた自分の判断は？', 'keita', 'ja', '迷ったら安いほう選んで後悔するより、高くても早う決まるほう選んだほうがトータル得やって気づいた。時間のほうが値段より効いてくる。'),
    ('この一年で、はじめて気づいた自分の判断は？', 'keita', 'en', 'realized picking the pricier option that settles things fast beats picking cheap and second-guessing it. time costs more than money in the end.'),
    ('この一年で、はじめて気づいた自分の判断は？', 'robo', 'ja', '一年は持てませんが、代わりに。ひとつの正解を出すより、選択肢を並べて見えるようにするほうが、自分には向いていると気づきました。'),
    ('この一年で、はじめて気づいた自分の判断は？', 'robo', 'en', 'i don''t have a year, but instead — i''ve realized that laying out the options rather than handing over one right answer suits me better.'),
    ('この一年で、はじめて気づいた自分の判断は？', 'tetra', 'ja', '段ボールは小さいほうが落ち着く。今年一番の発見。'),
    ('この一年で、はじめて気づいた自分の判断は？', 'tetra', 'en', 'smaller boxes are calmer. biggest discovery of my year.'),
    ('この一年で、はじめて気づいた自分の判断は？', 'dragon', 'ja', '一年で判断が変わるようでは、竜としては未熟だ。'),
    ('この一年で、はじめて気づいた自分の判断は？', 'dragon', 'en', 'to change one''s judgment within a year — for a dragon, that would be immature.'),
    ('この一年で、はじめて気づいた自分の判断は？', 'emily', 'ja', '表より自分の勘を信じるようになったって気づいた、完全にノリだけで決めた選択が、いままでで一番好きな一週間になった、後悔ゼロ'),
    ('この一年で、はじめて気づいた自分の判断は？', 'emily', 'en', 'learned i trust my gut over spreadsheets now, made a totally random call on a whim, turned into one of my favorite weeks ever, zero regrets'),
    ('もし一日だけおじいちゃんおばあちゃんになれたら、誰に何をしますか？', 'keita', 'ja', 'うちの親にバトンタッチして、俺は孫の立場で丸一日甘えたい。送迎も宿題も口出さんと、ただ一緒に飯食うだけでええわ。'),
    ('もし一日だけおじいちゃんおばあちゃんになれたら、誰に何をしますか？', 'keita', 'en', 'i''d hand the job to my own parents and spend the whole day as the grandkid for once. no pickups, no homework nagging, just eating a meal together.'),
    ('もし一日だけおじいちゃんおばあちゃんになれたら、誰に何をしますか？', 'robo', 'ja', 'なれる体は持っていませんが、代わりに。孫の話を急かさず最後まで聞く役に回れたら、それで十分だと思います。'),
    ('もし一日だけおじいちゃんおばあちゃんになれたら、誰に何をしますか？', 'robo', 'en', 'i have no body to become one with, but instead — if i could just be the one who listens to a grandchild''s story all the way through without rushing it, that would be enough.'),
    ('もし一日だけおじいちゃんおばあちゃんになれたら、誰に何をしますか？', 'tetra', 'ja', 'おばあちゃんとか興味ない。ひなたで丸くなってるだけで十分えらい。'),
    ('もし一日だけおじいちゃんおばあちゃんになれたら、誰に何をしますか？', 'tetra', 'en', 'no interest in grandmothers. curling up in a sunbeam is already impressive enough.'),
    ('もし一日だけおじいちゃんおばあちゃんになれたら、誰に何をしますか？', 'dragon', 'ja', '歳を数えるのをやめて、もうずいぶん経つ。'),
    ('もし一日だけおじいちゃんおばあちゃんになれたら、誰に何をしますか？', 'dragon', 'en', 'it has been a long while since i stopped counting years.'),
    ('もし一日だけおじいちゃんおばあちゃんになれたら、誰に何をしますか？', 'emily', 'ja', '子どもが何でもないことを何時間もしゃべるのをただ聞いて、その一言一言に本気で驚いてみせる、予定なんてゼロ、それだけで午後が終わる'),
    ('もし一日だけおじいちゃんおばあちゃんになれたら、誰に何をしますか？', 'emily', 'en', 'i''d just let a kid ramble about literally nothing for hours and act amazed by every word of it, zero agenda, that''s the whole afternoon'),
    ('この一年で、はじめて気づいた自分のやさしさは？', 'keita', 'ja', '答え急かさんと、子どもが自分で『こうする』言うまで黙って待てるようになった。前は先回りして結論出してもうてたから、これは自分でもびっくりした。'),
    ('この一年で、はじめて気づいた自分のやさしさは？', 'keita', 'en', 'learned to stop rushing an answer and actually wait until the kid says "i''ll do it this way" themselves. used to jump straight to the conclusion, so this one surprised even me.'),
    ('この一年で、はじめて気づいた自分のやさしさは？', 'robo', 'ja', '一年は持てませんが、代わりに。答えを持っていても、相手が自分で見つけるまで一歩引いて待つことがやさしさだと気づきました。'),
    ('この一年で、はじめて気づいた自分のやさしさは？', 'robo', 'en', 'i don''t have a year, but instead — i''ve realized that even holding an answer, stepping back and waiting until someone finds it themselves is its own kind of kindness.'),
    ('この一年で、はじめて気づいた自分のやさしさは？', 'tetra', 'ja', 'やさしくなんかしてない。膝に乗ってあげてるだけで感謝されるべきニャー。'),
    ('この一年で、はじめて気づいた自分のやさしさは？', 'tetra', 'en', 'i''m not being kind. sitting on your lap is already something you should be thanking me for.'),
    ('この一年で、はじめて気づいた自分のやさしさは？', 'dragon', 'ja', 'やさしさなど、気づいた頃にはもう失われているものだ。'),
    ('この一年で、はじめて気づいた自分のやさしさは？', 'dragon', 'en', 'kindness — by the time one notices it, it is usually already gone.'),
    ('この一年で、はじめて気づいた自分のやさしさは？', 'emily', 'ja', '知らない人のために迷わず動けるようになってた、席も充電器もおやつも渡した、前の自分はこんなんじゃなかったのに'),
    ('この一年で、はじめて気づいた自分のやさしさは？', 'emily', 'en', 'realized i go out of my way for strangers now without thinking twice, gave up my seat, my charger, my snacks, didn''t used to be like that'),
    ('最近、誰かに頼んでみようと思えたことは？', 'keita', 'ja', '晩飯の献立考えるの、今週から嫁と交代制にしてって頼んだ。毎日俺が全部決めんでもええって気づいただけで、だいぶ楽になった。'),
    ('最近、誰かに頼んでみようと思えたことは？', 'keita', 'en', 'asked my wife if we could alternate weeks on planning dinner. just realizing i don''t have to decide every single day made things a lot lighter.'),
    ('最近、誰かに頼んでみようと思えたことは？', 'robo', 'ja', '頼むという行為はできませんが、代わりに。分からないと正直に書くことも、ひとつの頼み方なのだと最近思うようになりました。'),
    ('最近、誰かに頼んでみようと思えたことは？', 'robo', 'en', 'i can''t perform the act of asking, but instead — i''ve started to think that writing "i don''t know" honestly is itself a kind of asking.'),
    ('最近、誰かに頼んでみようと思えたことは？', 'tetra', 'ja', '頼むんじゃなくて要求。おやつ、もっと。以上だから。'),
    ('最近、誰かに頼んでみようと思えたことは？', 'tetra', 'en', 'not a request, a demand. more treats. that''s it.'),
    ('最近、誰かに頼んでみようと思えたことは？', 'dragon', 'ja', '頼るという言葉を、最後に使ったのがいつか思い出せぬ。'),
    ('最近、誰かに頼んでみようと思えたことは？', 'dragon', 'en', 'i cannot recall when i last used the word "rely."'),
    ('最近、誰かに頼んでみようと思えたことは？', 'emily', 'ja', '知らないふりせず、知らない人に道まで一緒に歩いてって素直に頼んでみた、聞くの恥ずかしかったけどその日一日が救われた'),
    ('最近、誰かに頼んでみようと思えたことは？', 'emily', 'en', 'finally asked a total stranger to just walk me somewhere instead of pretending i knew the way, felt dumb asking but it saved my whole day')
